// Compass points that differ in Dutch; the others are written the same
const CARDINALS = {
  en: {},
  nl: { NE: 'NO', E: 'O', SE: 'ZO', S: 'Z', SW: 'ZW' }
};

// The setting wins when it is en or nl (any case); 'device' or empty uses the device locale; anything else is en
function resolveLanguage(setting, locale) {
  const chosen = String(setting ?? '').trim();
  const source = chosen === '' || chosen.toLowerCase() === 'device' ? locale : chosen;
  const code = String(source ?? '')
    .trim()
    .slice(0, 2)
    .toLowerCase();
  return STRINGS[code] ? code : 'en';
}

function fill(template, values) {
  return String(template).replace(/\{(\w+)\}/g, (_, key) => (values && values[key] !== undefined ? values[key] : ''));
}

function cardinalText(code, lang) {
  const language = STRINGS[lang] ? lang : 'en';
  return CARDINALS[language][code] || code;
}

function conditionsText(window, lang) {
  const language = STRINGS[lang] ? lang : 'en';
  const text = STRINGS[language];
  const dry = window.qualifies && window.precipProbMax <= DRY_MAX_PROBABILITY;
  const cardinal = cardinalText(window.windFromCardinal, language);
  const temp = Math.round(window.apparentTempAvg) || 0; // `|| 0` turns -0 into 0
  return {
    sky: dry ? text.dry : `${text.rain} ${window.precipProbMax}%`,
    wind: `${window.windAvg} ${text.speed} ${cardinal}`,
    temp: `${temp}°C`
  };
}

function finiteOrZero(value) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function formatKm(meters, lang) {
  const text = (Math.round(finiteOrZero(meters) / 100) / 10).toFixed(1);
  return lang === 'nl' ? text.replace('.', ',') : text;
}

function formatDuration(seconds) {
  const minutes = Math.round(finiteOrZero(seconds) / 60);
  return `${Math.floor(minutes / 60)}:${String(minutes % 60).padStart(2, '0')}`;
}

function formatPace(secondsPerKm) {
  const total = Math.round(finiteOrZero(secondsPerKm));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}

const FALLBACK_ZONE = 'UTC';
// The API's clock: two-digit hours, optional minutes (lib/params.js)
const CLOCK_TEXT = /^(\d{2})(?::(\d{2}))?$/;
const DAY_MS = 86400000;

// Intl in TRMNL has English data only: always en-US, parts, never a locale string
function zonedParts(ms, timeZone) {
  const options = {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23'
  };
  let formatter;
  try {
    formatter = new Intl.DateTimeFormat('en-US', { ...options, timeZone: timeZone || FALLBACK_ZONE });
  } catch {
    formatter = new Intl.DateTimeFormat('en-US', { ...options, timeZone: FALLBACK_ZONE });
  }
  const parts = {};
  for (const part of formatter.formatToParts(new Date(ms))) parts[part.type] = part.value;
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour) % 24,
    minute: Number(parts.minute),
    second: Number(parts.second)
  };
}

const pad = value => String(value).padStart(2, '0');

function localDate(ms, timeZone) {
  const { year, month, day } = zonedParts(ms, timeZone);
  return `${year}-${pad(month)}-${pad(day)}`;
}

function localTime(ms, timeZone) {
  const { hour, minute } = zonedParts(ms, timeZone);
  return `${pad(hour)}:${pad(minute)}`;
}

function dateToUtcMs(date) {
  const [year, month, day] = date.split('-').map(Number);
  return Date.UTC(year, month - 1, day);
}

function addDays(date, days) {
  return new Date(dateToUtcMs(date) + days * DAY_MS).toISOString().slice(0, 10);
}

// Monday is 0
function dayOfWeek(date) {
  return (new Date(dateToUtcMs(date)).getUTCDay() + 6) % 7;
}

function weekDates(date) {
  const monday = addDays(date, -dayOfWeek(date));
  return Array.from({ length: 7 }, (_, index) => addDays(monday, index));
}

// The week number of the Thursday of this date's week, counted in that Thursday's year
function isoWeek(date) {
  const thursday = addDays(date, 3 - dayOfWeek(date));
  const firstOfYear = `${thursday.slice(0, 4)}-01-01`;
  const days = Math.round((dateToUtcMs(thursday) - dateToUtcMs(firstOfYear)) / DAY_MS);
  return Math.floor(days / 7) + 1;
}

// The instant at which the wall clock in the zone shows `date` and `hour` (24 is the next midnight). Two passes
// correct for a UTC offset that differs at the guess and at the result (DST change in between).
function zonedWall(date, hour, timeZone) {
  const wall = dateToUtcMs(date) + hour * 3600000;
  const offsetAt = ms => {
    const p = zonedParts(ms, timeZone);
    return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - Math.floor(ms / 1000) * 1000;
  };
  const first = wall - offsetAt(wall);
  return wall - offsetAt(first);
}

function zonedMidnight(date, timeZone) {
  return zonedWall(date, 0, timeZone);
}

// 'HH' or 'HH:MM' as minutes since midnight, as the API reads it; 24:00 only as an end. null when invalid.
function clockMinutes(text, isEnd) {
  const match = CLOCK_TEXT.exec(text);
  if (!match) return null;
  const hours = Number(match[1]);
  const minutes = match[2] === undefined ? 0 : Number(match[2]);
  if (minutes > 59 || hours > 24 || (hours === 24 && (!isEnd || minutes !== 0))) return null;
  return hours * 60 + minutes;
}

// Ranges in minutes, sorted, exactly as the API accepts them; null for anything it answers 400 to
function availabilityRanges(avail) {
  const ranges = [];
  const pieces = String(avail ?? '')
    .replace(/ /g, '')
    .split(',');
  for (const piece of pieces) {
    const bounds = piece.split('-');
    if (bounds.length !== 2) return null;
    const start = clockMinutes(bounds[0], false);
    const end = clockMinutes(bounds[1], true);
    if (start === null || end === null || end <= start) return null;
    ranges.push({ start, end });
  }
  ranges.sort((a, b) => a.start - b.start);
  for (let index = 1; index < ranges.length; index += 1) {
    if (ranges[index].start < ranges[index - 1].end) return null;
  }
  return ranges;
}

// End of the latest range that local day; 24:00 is the next midnight. Hours the API rejects: the end of the day.
function availabilityEnd(avail, date, timeZone) {
  const ranges = availabilityRanges(avail);
  const latest = ranges ? Math.max(...ranges.map(range => range.end)) : 24 * 60;
  return zonedWall(date, latest / 60, timeZone);
}

const DEFAULT_AVAILABILITY = '07-09,12-14,17-21';
const DEFAULT_DARK = 'avoid';
const DEFAULT_RAIN = '40';
const DEFAULT_SPORT = 'running';
const DEFAULT_LANGUAGE = 'device';
const WINDOW_URL = 'https://run.xadi.eu/api/window';
const NUMBER_TEXT = /^-?\d+(\.\d+)?$/;

function textOr(value, fallback) {
  return typeof value === 'string' && value !== '' ? value : fallback;
}

// A coordinate in the lat_lon text, rounded to 2 decimals like the polling URL does; null when not a number
function roundCoordinate(text, limit) {
  const trimmed = text.trim();
  if (!NUMBER_TEXT.test(trimmed)) return null;
  const value = Number(trimmed);
  if (Math.abs(value) > limit) return null;
  return Math.round(value * 100) / 100 || 0; // `|| 0` turns -0 into 0
}

function readLocation(value) {
  const parts = typeof value === 'string' ? value.split(',') : [];
  const lat = parts.length === 2 ? roundCoordinate(parts[0], 90) : null;
  const lon = parts.length === 2 ? roundCoordinate(parts[1], 180) : null;
  return lat === null || lon === null ? { lat: null, lon: null } : { lat, lon };
}

// Never throws: a missing trmnl, null custom_fields_values or non-string values give the defaults
function readSettings(input) {
  const trmnl = input && typeof input === 'object' ? input.trmnl : null;
  const plugin = trmnl && typeof trmnl === 'object' ? trmnl.plugin_settings : null;
  const fields = plugin && typeof plugin === 'object' ? plugin.custom_fields_values : null;
  const values = fields && typeof fields === 'object' ? fields : {};
  const { lat, lon } = readLocation(values.lat_lon);
  return {
    token: textOr(values.tredict_token, ''),
    lat,
    lon,
    availability: textOr(values.availability, DEFAULT_AVAILABILITY).replace(/ /g, ''),
    dark: textOr(values.dark, DEFAULT_DARK),
    rain: textOr(values.rain, DEFAULT_RAIN),
    sport: textOr(values.sport, DEFAULT_SPORT),
    language: textOr(values.language, DEFAULT_LANGUAGE),
    hasLocation: lat !== null && lon !== null
  };
}

// The same URL settings.yml renders for polling; Liquid's url_encode turns spaces into +
function windowUrl(settings) {
  if (!settings || !settings.hasLocation) return null;
  const avail = encodeURIComponent(settings.availability).replace(/%20/g, '+');
  const { lat, lon, dark, rain } = settings;
  return `${WINDOW_URL}?lat=${lat}&lon=${lon}&avail=${avail}&dark=${dark}&rain=${rain}`;
}

const TREDICT_BASE = 'https://www.tredict.com/api/oauth/v2/';
const DEADLINE_MS = 4000;
const CALL_TIMEOUT_MS = 3000;
const MIN_START_MS = 500;

// From the day before this local Monday to the end of the day after next Monday, as UTC ISO strings
function tredictRange(now, timeZone) {
  const monday = weekDates(localDate(now, timeZone))[0];
  return {
    from: new Date(zonedMidnight(addDays(monday, -1), timeZone)).toISOString(),
    to: new Date(zonedMidnight(addDays(monday, 9), timeZone) - 1).toISOString()
  };
}

function tredictUrls(range) {
  const query = `startDate=${encodeURIComponent(range.from)}&endDate=${encodeURIComponent(range.to)}`;
  return {
    plan: `${TREDICT_BASE}plannedTrainingList?${query}`,
    activities: `${TREDICT_BASE}activityList?pageSize=50&extendedSummary=1`,
    efforts: `${TREDICT_BASE}efforts`
  };
}

function detailUrl(id) {
  return `${TREDICT_BASE}activity/${encodeURIComponent(id)}?extraValues=1`;
}

// Whole seconds from a Retry-After header, or null when absent, unreadable or an HTTP date
function retryAfterSeconds(response) {
  try {
    const value = response.headers.get('retry-after');
    return typeof value === 'string' && /^\d+$/.test(value) ? Number(value) : null;
  } catch {
    return null;
  }
}

// Never rejects. The fetch races its own timer, so one that ignores the abort signal still settles.
async function fetchJson(fetchFn, url, token, timeoutMs = 3000) {
  if (!token) return { ok: false, kind: 'auth', status: null };
  const unavailable = status => ({ ok: false, kind: 'unavailable', status });
  let timer;
  try {
    const timeout = new Promise(resolve => {
      timer = setTimeout(() => resolve(null), timeoutMs);
    });
    const request = (async () => {
      const response = await fetchFn(url, {
        headers: { Authorization: `Bearer ${token}`, Accept: 'application/json;charset=UTF-8' },
        // Serial calls rely on this signal tearing the request down at the timeout; the race timer only settles the
        // promise, so without it a timed-out request would overlap the next one.
        signal: AbortSignal.timeout(timeoutMs)
      });
      const status = response.status;
      if (status === 401) return { ok: false, kind: 'paused', status };
      if (status === 403) return { ok: false, kind: 'auth', status };
      if (status === 404) return { ok: false, kind: 'missing', status };
      if (status === 429) return { ok: false, kind: 'rate', status, retryAfterS: retryAfterSeconds(response) };
      if (status === 402) return { ok: false, kind: 'payment', status };
      if (!(status >= 200 && status < 300)) return unavailable(status);
      try {
        return { ok: true, data: JSON.parse(await response.text()) };
      } catch {
        return unavailable(status);
      }
    })();
    request.catch(() => {});
    return (await Promise.race([request, timeout])) || unavailable(null);
  } catch {
    return unavailable(null);
  } finally {
    clearTimeout(timer);
  }
}

// Runs Tredict calls strictly one after another under one deadline and stops after a 429. call() never rejects.
function tredictSequence({ fetch, token, clock = Date.now, deadlineMs = DEADLINE_MS }) {
  const deadline = clock() + deadlineMs;
  let last = Promise.resolve();
  let rate = null;

  const run = async url => {
    if (rate) return { ok: false, kind: 'skipped' };
    const remaining = deadline - clock();
    if (remaining < MIN_START_MS) return { ok: false, kind: 'unavailable', status: null };
    const result = await fetchJson(fetch, url, token, Math.min(CALL_TIMEOUT_MS, remaining));
    if (result.kind === 'rate') rate = { retryAfterS: result.retryAfterS };
    return result;
  };

  return {
    call(url) {
      const result = last.then(() => run(url));
      last = result.catch(() => {});
      return result.catch(() => ({ ok: false, kind: 'unavailable', status: null }));
    },
    remaining: () => deadline - clock(),
    stopped: () => rate !== null,
    rate: () => rate
  };
}

const INTENSITY_PER_RUN = 3;
const DETAIL_MIN_MS = 1000;
const MAX_ID_LENGTH = 64;
const BAR_WIDTH = 360;
const MIN_SEGMENT_WIDTH = 4;
const KINDS = ['low', 'moderate', 'high'];
const LABEL_KEYS = { low: 'intensityLow', moderate: 'intensityModerate', high: 'intensityHigh' };

const isSeconds = value => typeof value === 'number' && Number.isFinite(value) && value >= 0;

function readIntensityCache(value) {
  const map = new Map();
  if (!Array.isArray(value)) return map;
  for (const entry of value) {
    if (!Array.isArray(entry) || entry.length !== 4) continue;
    const [id, low, moderate, high] = entry;
    if (typeof id !== 'string' || id === '' || id.length > MAX_ID_LENGTH) continue;
    if (![low, moderate, high].every(isSeconds)) continue;
    map.set(id, [low, moderate, high]);
  }
  return map;
}

function cacheList(map, ids) {
  return ids.filter(id => map.has(id)).map(id => [id, ...map.get(id)]);
}

function intensityOf(data) {
  const heartrate =
    data && data.summary && data.summary.intensityDistribution ? data.summary.intensityDistribution.heartrate : null;
  if (!heartrate) return [0, 0, 0];
  return ['0', '1', '2'].map(key => (isSeconds(heartrate[key]) ? heartrate[key] : 0));
}

function formatTotal(seconds) {
  const minutes = Math.floor(seconds / 60);
  return `${Math.floor(minutes / 60)}:${String(minutes % 60).padStart(2, '0')}`;
}

// Whole percentages summing to 100: floor each, give the leftover to the largest remainders (ties: low first).
function percentages(seconds, total) {
  const exact = seconds.map(value => (value / total) * 100);
  const result = exact.map(Math.floor);
  const order = exact
    .map((value, index) => index)
    .sort((a, b) => exact[b] - result[b] - (exact[a] - result[a]) || a - b);
  let left = 100 - result.reduce((sum, value) => sum + value, 0);
  for (const index of order) {
    if (left <= 0) break;
    result[index] += 1;
    left -= 1;
  }
  return result;
}

function widths(seconds, total) {
  const result = seconds.map(value =>
    value > 0 ? Math.max(MIN_SEGMENT_WIDTH, Math.round((value / total) * BAR_WIDTH)) : 0
  );
  const largest = seconds.indexOf(Math.max(...seconds));
  result[largest] += BAR_WIDTH - result.reduce((sum, value) => sum + value, 0);
  return result;
}

function intensityView(entries, lang) {
  const seconds = [0, 1, 2].map(level => entries.reduce((sum, entry) => sum + entry[level], 0));
  const total = seconds.reduce((sum, value) => sum + value, 0);
  if (total <= 0) return null;
  const text = STRINGS[lang] || STRINGS.en;
  const barWidths = widths(seconds, total);
  const segments = [];
  let x = 0;
  KINDS.forEach((kind, index) => {
    if (seconds[index] <= 0) return;
    segments.push({ kind, x, width: barWidths[index] });
    x += barWidths[index];
  });
  const shares = percentages(seconds, total);
  return {
    heading: fill(text.intensityHeading, { time: formatTotal(total) }),
    segments,
    labels: KINDS.map((kind, index) => `${text[LABEL_KEYS[kind]]} ${shares[index]}%`)
  };
}

const ITEMS_PER_DAY = 2;
const GARMIN_FALLBACK = 'Garmin';
const SPORT_KEYS = {
  running: 'sportRunning',
  cycling: 'sportCycling',
  swimming: 'sportSwimming',
  strength: 'sportStrength'
};

const isPositive = value => Number.isFinite(value) && value > 0;

function isZone(value) {
  if (typeof value !== 'string' || value === '') return false;
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

// A plan's numeric `timezone` is an offset fixed when it was made (wrong across DST), so the user's zone decides
function planDay(plan, tz) {
  return localDate(Date.parse(plan.date), tz);
}

function activityDay(activity, tz) {
  return localDate(Date.parse(activity.date), isZone(activity.timezone) ? activity.timezone : tz);
}

// The Garmin attribution text of an activity from the Garmin API, else null
function garminText(activity) {
  if (!activity || activity.isFromGarminApi !== true) return null;
  return typeof activity.attribution === 'string' && activity.attribution.trim()
    ? activity.attribution
    : GARMIN_FALLBACK;
}

const matchesSport = (entry, sport) => sport === 'all' || entry.sportType === sport;

// Copies only the fields the screen needs: never the summary (it holds start coordinates)
function weekItem(kind, title, sportType, metrics) {
  const item = { kind, title: typeof title === 'string' ? title : '', sportType: String(sportType ?? '') };
  for (const [key, value] of Object.entries(metrics)) {
    if (isPositive(value)) item[key] = value;
  }
  return item;
}

function activityMetrics(activity) {
  const summary = activity.summary && typeof activity.summary === 'object' ? activity.summary : {};
  const distanceM = summary.distance;
  const durationS = summary.duration;
  let paceSPerKm = summary.pace;
  if (!isPositive(paceSPerKm) && isPositive(distanceM) && isPositive(durationS)) {
    paceSPerKm = durationS / (distanceM / 1000);
  }
  if (!isPositive(distanceM)) paceSPerKm = undefined;
  return { distanceM, durationS, paceSPerKm, heartrate: summary.heartrate };
}

function buildWeek({ plans, activities, now, tz, sport = 'running' }) {
  const today = localDate(now, tz);
  const dates = weekDates(today);
  const byDate = new Map(dates.map(date => [date, []]));
  const totals = { doneDistanceM: 0, doneDurationS: 0 };
  let plannedDistanceM = 0;
  let plannedDurationS = 0;
  let planCount = 0;

  const seen = (Array.isArray(activities) ? activities : []).filter(activity => {
    if (!activity || typeof activity !== 'object') return false;
    const at = Date.parse(activity.date);
    return Number.isFinite(at) && at <= now;
  });
  const activityById = new Map(seen.filter(activity => activity.id).map(activity => [activity.id, activity]));
  const used = new Set();

  const done = [];
  const addDone = (date, at, item, activity) => {
    if (activity.id) done.push({ at, id: String(activity.id), garmin: garminText(activity) });
    byDate.get(date).push({ at, item, activity });
    totals.doneDistanceM += item.distanceM || 0;
    totals.doneDurationS += item.durationS || 0;
  };

  for (const plan of Array.isArray(plans) ? plans : []) {
    if (!plan || typeof plan !== 'object' || !matchesSport(plan, sport)) continue;
    const at = Date.parse(plan.date);
    if (!Number.isFinite(at)) continue;
    const date = planDay(plan, tz);
    if (!byDate.has(date)) continue;
    planCount += 1;
    if (isPositive(plan.distance)) plannedDistanceM += plan.distance;
    if (isPositive(plan.duration)) plannedDurationS += plan.duration;

    const activity = plan.executedTrainingId ? activityById.get(plan.executedTrainingId) : undefined;
    if (activity && !used.has(activity)) {
      used.add(activity);
      const item = weekItem('done', plan.title, activity.sportType, activityMetrics(activity));
      addDone(date, Date.parse(activity.date), item, activity);
      continue;
    }
    const planned = { distanceM: plan.distance, durationS: plan.duration };
    let kind = 'planned';
    if (date < today) kind = plan.executedTrainingId ? 'done' : 'missed';
    const item =
      kind === 'done'
        ? weekItem(kind, plan.title, plan.sportType, {})
        : weekItem(kind, plan.title, plan.sportType, planned);
    byDate.get(date).push({ at, item });
  }

  for (const activity of seen) {
    if (used.has(activity) || !matchesSport(activity, sport)) continue;
    const date = activityDay(activity, tz);
    if (!byDate.has(date)) continue;
    addDone(
      date,
      Date.parse(activity.date),
      weekItem('unplanned', activity.title, activity.sportType, activityMetrics(activity)),
      activity
    );
  }

  const garmin = [];
  const days = dates.map(date => {
    const entries = byDate.get(date).sort((a, b) => a.at - b.at);
    const shown = entries.slice(0, ITEMS_PER_DAY);
    for (const { activity } of shown) {
      const text = garminText(activity);
      if (text !== null && !garmin.includes(text)) garmin.push(text);
    }
    return {
      date,
      isToday: date === today,
      isPast: date < today,
      items: shown.map(entry => entry.item),
      more: entries.length - shown.length
    };
  });

  if (planCount > 0) {
    totals.plannedDistanceM = plannedDistanceM;
    totals.plannedDurationS = plannedDurationS;
  }
  done.sort((a, b) => b.at - a.at);
  return {
    week: isoWeek(today),
    days,
    totals,
    garmin,
    done: done.map(({ id, garmin: text }) => ({ id, garmin: text }))
  };
}

function itemTitle(item, text) {
  if (item.title.trim() !== '') return item.title;
  return text[SPORT_KEYS[item.sportType] || 'sportOther'];
}

const minutesText = (seconds, text) => {
  const minutes = Math.round(seconds / 60);
  return minutes > 0 ? fill(text.minutes, { n: minutes }) : '';
};

function itemText(item, lang, text) {
  const parts = [];
  if (item.kind === 'done' || item.kind === 'unplanned') {
    if (item.distanceM) {
      parts.push(`${formatKm(item.distanceM, lang)} km`);
      if (item.paceSPerKm) parts.push(formatPace(item.paceSPerKm));
    } else {
      parts.push(itemTitle(item, text));
      if (item.durationS) parts.push(minutesText(item.durationS, text));
    }
    if (item.heartrate) parts.push(String(Math.round(item.heartrate)));
    return `✓ ${parts.filter(Boolean).join(' · ')}`;
  }
  parts.push(itemTitle(item, text));
  if (item.durationS) parts.push(minutesText(item.durationS, text));
  else if (item.distanceM) parts.push(`${formatKm(item.distanceM, lang)} km`);
  const plain = parts.filter(Boolean).join(' · ');
  return item.kind === 'missed' ? `✗ ${plain}` : plain;
}

function weekFooter(totals, lang) {
  const doneKm = formatKm(totals.doneDistanceM, lang);
  const doneTime = formatDuration(totals.doneDurationS);
  // A planned half is left out when nothing planned has that value, so it never reads "/ 0:00" or "/ 0.0 km"
  const km = isPositive(totals.plannedDistanceM) ? `${doneKm} / ${formatKm(totals.plannedDistanceM, lang)}` : doneKm;
  const time = isPositive(totals.plannedDurationS)
    ? `${doneTime} / ${formatDuration(totals.plannedDurationS)}`
    : doneTime;
  return `${km} km · ${time}`;
}

// Text stays verbatim: escaping is the markup's job
function weekView(week, lang) {
  const language = STRINGS[lang] ? lang : 'en';
  const text = STRINGS[language];
  return {
    title: `${text.week} ${week.week}`,
    days: week.days.map((day, index) => ({
      label: text.days[index],
      today: day.isToday,
      items: day.items.map(item => ({ kind: item.kind, text: itemText(item, language, text) })),
      more: day.more > 0 ? `+${day.more}` : ''
    })),
    footer: weekFooter(week.totals, language),
    garmin: week.garmin.slice()
  };
}

// Tredict's model: exponentially decaying sums, performance = 1.66 · fitness − 2 · fatigue
const FORM_CONSTANTS = { fitnessDays: 14, fatigueDays: 9, fitnessWeight: 1.66, fatigueWeight: 2 };
const DEFAULT_BACK_DAYS = 42;
const DEFAULT_AHEAD_DAYS = 7;
// The endpoint covers a year; older keys add nothing visible but loop time
const MAX_WARMUP_DAYS = 730;
const DATE_TEXT = /^\d{4}-\d{2}-\d{2}$/;
const CHART_WIDTH = 360;
const CHART_HEIGHT = 150;
const CHART_PADDING = 6;
const EFFORT_KEY = /^(\d{4})(\d{2})(\d{2})$/;
const SVG_PATH = /^[ML0-9. -]*$/;
const MINUS = '−';

const effortKey = date => date.replace(/-/g, '');

// Confirmed efforts for past days; all entries for today and later (a done plan's unconfirmed entry is already gone)
function dayLoad(entries, countUnconfirmed) {
  if (!Array.isArray(entries)) return 0;
  let load = 0;
  for (const entry of entries) {
    if (!Array.isArray(entry)) continue;
    const value = Number(entry[0]);
    const unconfirmed = Boolean(entry[1] && typeof entry[1] === 'object' && entry[1].unconfirmed);
    if (entry[0] === null || !Number.isFinite(value) || (unconfirmed && !countUnconfirmed)) continue;
    load += value;
  }
  return load;
}

// Fitness and fatigue from 0 on the first day with data; the value is Tredict's performance after that day's load
function formSeries({
  efforts,
  today,
  back = DEFAULT_BACK_DAYS,
  ahead = DEFAULT_AHEAD_DAYS,
  constants = FORM_CONSTANTS
}) {
  const source = efforts && typeof efforts === 'object' ? efforts : {};
  const keys = Object.keys(source)
    .filter(key => EFFORT_KEY.test(key))
    .sort();
  if (keys.length === 0 || !DATE_TEXT.test(String(today))) return { points: [], today: null };

  const start = addDays(today, -back);
  const earliest = keys[0].replace(EFFORT_KEY, '$1-$2-$3');
  const oldest = addDays(start, -MAX_WARMUP_DAYS);
  const first = earliest < oldest ? oldest : earliest;
  const end = addDays(today, ahead);
  const fitnessDecay = Math.exp(-1 / constants.fitnessDays);
  const fatigueDecay = Math.exp(-1 / constants.fatigueDays);
  const forms = new Map();
  let fitness = 0;
  let fatigue = 0;
  for (let date = first; date <= end; date = addDays(date, 1)) {
    const load = dayLoad(source[effortKey(date)], date >= today);
    fitness = fitness * fitnessDecay + load;
    fatigue = fatigue * fatigueDecay + load;
    if (date >= start) forms.set(date, constants.fitnessWeight * fitness - constants.fatigueWeight * fatigue);
  }

  const points = [];
  for (let date = start; date <= end; date = addDays(date, 1)) {
    points.push({ date, form: forms.get(date) ?? 0, planned: date > today });
  }
  const todayPoint = points.find(point => point.date === today);
  return { points, today: todayPoint ? todayPoint.form : null };
}

const coordinate = value => {
  const text = value.toFixed(1);
  return text === '-0.0' ? '0.0' : text;
};

const safePath = path => (SVG_PATH.test(path) ? path : '');
const safeNumber = value => (Number.isFinite(value) ? value : 0);

function roundedForm(value) {
  if (!Number.isFinite(value)) return '';
  const rounded = Math.round(value) || 0;
  return rounded < 0 ? `${MINUS}${-rounded}` : String(rounded);
}

function chartPath(coordinates) {
  if (coordinates.length === 0) return '';
  return coordinates.map(([x, y], index) => `${index === 0 ? 'M' : 'L'}${coordinate(x)} ${coordinate(y)}`).join(' ');
}

function formLabels(back, ahead, text) {
  return {
    back: fill(back % 7 === 0 ? text.formWeeksBack : text.formDaysBack, { n: back % 7 === 0 ? back / 7 : back }),
    today: text.formToday,
    ahead: fill(text.formDaysAhead, { n: ahead })
  };
}

function formChart(series, lang) {
  const text = STRINGS[STRINGS[lang] ? lang : 'en'];
  const points = series && Array.isArray(series.points) ? series.points : [];
  if (points.length === 0) {
    return {
      heading: text.formLabel,
      today: '',
      pastPath: '',
      futurePath: '',
      zeroY: CHART_HEIGHT / 2,
      todayX: 0,
      labels: formLabels(DEFAULT_BACK_DAYS, DEFAULT_AHEAD_DAYS, text),
      empty: text.noTrainingData
    };
  }

  const values = points.map(point => (Number.isFinite(point.form) ? point.form : 0));
  const high = Math.max(0, ...values);
  const low = Math.min(0, ...values);
  const span = high - low || 1;
  const step = points.length > 1 ? CHART_WIDTH / (points.length - 1) : 0;
  const yOf = value => CHART_PADDING + ((high - value) / span) * (CHART_HEIGHT - 2 * CHART_PADDING);
  const coordinates = values.map((value, index) => [index * step, yOf(value)]);

  // Today is the last point that is not planned
  const firstPlanned = points.findIndex(point => point.planned);
  const todayIndex = firstPlanned === -1 ? points.length - 1 : Math.max(firstPlanned - 1, 0);
  const past = coordinates.slice(0, todayIndex + 1);
  const future = coordinates.slice(todayIndex);

  return {
    heading: text.formLabel,
    today: roundedForm(series.today),
    pastPath: safePath(chartPath(past)),
    futurePath: future.length > 1 ? safePath(chartPath(future)) : '',
    zeroY: safeNumber(Number(coordinate(yOf(0)))),
    todayX: safeNumber(Number(coordinate(coordinates[todayIndex][0]))),
    labels: formLabels(todayIndex, points.length - 1 - todayIndex, text),
    empty: ''
  };
}

const SESSION_STEP_MINUTES = 15;
const MAX_SESSION_MINUTES = 180;
const DEFAULT_SESSION_MINUTES = 60;
const FALLBACK_MINUTES = 60;
const STALE_WARNING = 'stale_data';
const EN_DASH = '–';
const HEADING_SEPARATOR = ' · ';

// Plans of the sport on that local day, not yet done, earliest first
function remainingPlans(plans, date, tz, sport) {
  return plans
    .filter(item => item && Number.isFinite(Date.parse(item.date)))
    .filter(item => matchesSport(item, sport) && !item.executedTrainingId && planDay(item, tz) === date)
    .sort((a, b) => Date.parse(a.date) - Date.parse(b.date));
}

// `duration` is in seconds; never estimated from distance
function sessionLength(planned) {
  const seconds = planned.duration;
  if (!Number.isFinite(seconds) || seconds <= 0) {
    return { minutes: DEFAULT_SESSION_MINUTES, reason: 'noDuration', overLimit: false };
  }
  const rounded = Math.max(SESSION_STEP_MINUTES, Math.ceil(seconds / 60 / SESSION_STEP_MINUTES) * SESSION_STEP_MINUTES);
  if (rounded > MAX_SESSION_MINUTES) return { minutes: MAX_SESSION_MINUTES, reason: 'planned', overLimit: true };
  return { minutes: rounded, reason: 'planned', overLimit: false };
}

function pickSession({ plans, now, tz, avail, sport = 'running' }) {
  const today = localDate(now, tz);
  const tomorrow = addDays(today, 1);
  const pastToday = now > availabilityEnd(avail, today, tz);
  const choose = (day, details) => ({ day, date: day === 'today' ? today : tomorrow, ...details });
  const unplanned = reason => ({ minutes: DEFAULT_SESSION_MINUTES, reason, overLimit: false });

  if (!Array.isArray(plans)) return choose(pastToday ? 'tomorrow' : 'today', unplanned('unknown'));

  const leftToday = remainingPlans(plans, today, tz, sport);
  if (!pastToday && leftToday.length > 0) return choose('today', sessionLength(leftToday[0]));

  const nextDay = remainingPlans(plans, tomorrow, tz, sport);
  if (nextDay.length > 0) return choose('tomorrow', sessionLength(nextDay[0]));

  const plannedToday = plans.some(
    item => item && Number.isFinite(Date.parse(item.date)) && matchesSport(item, sport) && planDay(item, tz) === today
  );
  return choose(!pastToday && !plannedToday ? 'today' : 'tomorrow', unplanned('noPlan'));
}

// The API contract's compass points
const WIND_CARDINALS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];

// A window the screen can print in full; anything less counts as missing, so the next option is used
function readableWindow(value) {
  if (!value || typeof value !== 'object') return null;
  const readable =
    Number.isFinite(Date.parse(value.start)) &&
    Number.isFinite(Date.parse(value.end)) &&
    Number.isFinite(value.precipProbMax) &&
    Number.isFinite(value.windAvg) &&
    Number.isFinite(value.apparentTempAvg) &&
    WIND_CARDINALS.includes(value.windFromCardinal);
  return readable ? value : null;
}

// The session's own window, else the longest shorter one, else the API's fallback
function chooseWindow(day, minutes) {
  const windows = day.windows && typeof day.windows === 'object' ? day.windows : {};
  const exact = readableWindow(windows[String(minutes)]);
  if (exact) return { kind: 'window', window: exact, minutes };
  for (let length = minutes - SESSION_STEP_MINUTES; length >= SESSION_STEP_MINUTES; length -= SESSION_STEP_MINUTES) {
    const shorter = readableWindow(windows[String(length)]);
    if (shorter) return { kind: 'shorter', window: shorter, minutes: length };
  }
  const fallback = readableWindow(day.fallback);
  if (fallback) return { kind: 'fallback', window: fallback, minutes: FALLBACK_MINUTES };
  return { kind: 'none', window: null, minutes };
}

function sessionHeading(session, text) {
  const dayWord = session.day === 'tomorrow' ? text.headingTomorrow : text.headingToday;
  let length = fill(text.minutes, { n: session.minutes });
  if (session.reason === 'noDuration') length += ` ${text.noDuration}`;
  if (session.reason === 'noPlan') length += `${HEADING_SEPARATOR}${text.noSession}`;
  if (session.overLimit) length += `${HEADING_SEPARATOR}${text.doesntFit}`;
  return `${dayWord}${HEADING_SEPARATOR}${length}`;
}

// The non-window kinds replace the length; "BEST TIME TODAY" would contradict them, TOMORROW still matters
function fallbackHeading(session, phrase, text) {
  return session.day === 'tomorrow' ? `${text.headingTomorrow}${HEADING_SEPARATOR}${phrase}` : phrase;
}

function windowHeading(choice, session, text) {
  if (choice.kind === 'window') return sessionHeading(session, text);
  if (choice.kind === 'shorter') return fallbackHeading(session, fill(text.onlyFits, { n: choice.minutes }), text);
  if (choice.kind === 'fallback') return fallbackHeading(session, text.noDryFallback, text);
  return fallbackHeading(session, text.noDryWindow, text);
}

function windowLines(choice, day, body, lang, text) {
  const tz = body.location && body.location.timezone;
  const lines = [];
  const chosen = choice.window;
  if (chosen) {
    const start = localTime(Date.parse(chosen.start), tz);
    const end = localTime(Date.parse(chosen.end), tz);
    const conditions = conditionsText(chosen, lang);
    lines.push(`${start}${EN_DASH}${end}`);
    lines.push([conditions.sky, conditions.wind, conditions.temp].join(HEADING_SEPARATOR));
    if (chosen.windFromCardinal) {
      lines.push(fill(text.windStart, { cardinal: cardinalText(chosen.windFromCardinal, lang) }));
    }
    if (day.sunset && Number.isFinite(Date.parse(day.sunset))) {
      lines.push(fill(text.darkAfter, { time: localTime(Date.parse(day.sunset), tz) }));
    }
  }
  if (Array.isArray(body.warnings) && body.warnings.includes(STALE_WARNING)) lines.push(text.weatherStale);
  return lines;
}

function windowPanel({ body, status, session, lang, hasLocation }) {
  const language = STRINGS[lang] ? lang : 'en';
  const text = STRINGS[language];
  const message = (kind, heading) => ({ kind, heading, lines: [] });

  if (!hasLocation) return message('noLocation', text.setLocation);
  if (!body || typeof body !== 'object' || !Array.isArray(body.days)) {
    return status === 400 ? message('badSettings', text.checkHours) : message('error', text.weatherUnavailable);
  }
  const day = body.days.find(entry => entry && typeof entry === 'object' && entry.date === session.date);
  if (!day) return message('error', text.weatherUnavailable);

  const choice = chooseWindow(day, session.minutes);
  return {
    kind: choice.kind,
    heading: windowHeading(choice, session, text),
    lines: windowLines(choice, day, body, language, text)
  };
}

const BOARD_VERSION = 1;
const REQUEST_TIMEOUT_MS = 3000;
const RETRY_PAUSE_MS = 30 * 60000;
// A Tredict 429 pauses calls for Retry-After seconds, clamped to this range
const TREDICT_PAUSE_MIN_S = 1800;
const TREDICT_PAUSE_MAX_S = 21600;
const SKIPPED = { ok: false, kind: 'skipped' };
const ATTRIBUTION_SEPARATOR = ' · ';
// Run panel kinds that used weather data, so they carry its attribution
const WEATHER_KINDS = ['window', 'shorter', 'fallback', 'none'];
const ITEM_KINDS = ['done', 'planned', 'missed', 'unplanned'];
const REUSED_PATH = /^[ML0-9. -]*$/;
const INTENSITY_KINDS = ['low', 'moderate', 'high'];

const isObject = value => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const textOf = value => (typeof value === 'string' ? value : '');
const finiteOf = value => (typeof value === 'number' && Number.isFinite(value) ? value : 0);
const isFiniteNumber = value => typeof value === 'number' && Number.isFinite(value);
const union = (...lists) => [...new Set(lists.flat())];

// The fixed output for anything unexpected: no input-derived text, never an error's text. Only the Tredict pause and
// the intensity cache carry over, from this run when it got that far, else from the previous output, so a throw can't
// drop them.
function errorBoard(now, previous, carry = {}) {
  const at = Number.isFinite(now) ? now : Date.now();
  let fetchedAtText;
  try {
    fetchedAtText = dayAndTime(at, 'UTC', STRINGS.en);
  } catch {
    fetchedAtText = '';
  }
  let tredictRetryAt;
  try {
    tredictRetryAt = carry.tredictRetryAt || recentTredictPause(previous, at);
  } catch {
    tredictRetryAt = null;
  }
  let intensityCache;
  try {
    intensityCache = Array.isArray(carry.intensityCache) ? carry.intensityCache : carriedCache(previous);
  } catch {
    intensityCache = [];
  }
  return {
    v: BOARD_VERSION,
    lang: 'en',
    fetchedAt: new Date(at).toISOString(),
    fetchedAtText,
    tredict: { state: 'unavailable', message: STRINGS.en.tredictUnavailable },
    tredictAt: null,
    tredictAtText: '',
    week: null,
    form: null,
    intensity: null,
    run: { kind: 'error', heading: STRINGS.en.weatherUnavailable, lines: [] },
    weatherRetryAt: null,
    tredictRetryAt,
    intensityCache,
    attribution: ''
  };
}

function dayAndTime(ms, tz, text) {
  return `${text.days[dayOfWeek(localDate(ms, tz))]} ${localTime(ms, tz)}`;
}

// Tokenless, like the polling request. Never rejects; races its own timer like fetchJson.
async function fetchWindow(fetchFn, url, timeoutMs) {
  let timer;
  try {
    const timeout = new Promise(resolve => {
      timer = setTimeout(() => resolve(null), timeoutMs);
    });
    const request = (async () => {
      const response = await fetchFn(url, { signal: AbortSignal.timeout(timeoutMs) });
      const status = response && Number.isInteger(response.status) ? response.status : null;
      if (!(status >= 200 && status < 300)) return { status, body: null };
      try {
        return { status, body: JSON.parse(await response.text()) };
      } catch {
        return { status, body: null };
      }
    })();
    request.catch(() => {});
    return (await Promise.race([request, timeout])) || { status: null, body: null };
  } catch {
    return { status: null, body: null };
  } finally {
    clearTimeout(timer);
  }
}

// The previous retry's time, when it is under 30 minutes old and the weather was unavailable then: anchored to the
// retry, so skipping doesn't renew it. Any other previous result (badSettings, a window) retries again.
function recentWeatherRetry(previous, now) {
  if (!isObject(previous) || typeof previous.weatherRetryAt !== 'string') return null;
  if (!isObject(previous.run) || previous.run.kind !== 'error') return null;
  const at = Date.parse(previous.weatherRetryAt);
  const age = now - at;
  return age >= 0 && age < RETRY_PAUSE_MS ? new Date(at).toISOString() : null;
}

// The previous Tredict pause while it is in force: anchored to the 429, so skipping doesn't renew it. A pause more
// than the longest clamp ahead (hand-edited, clock skew) is ignored rather than pausing the board for good.
function recentTredictPause(previous, now) {
  if (!isObject(previous) || typeof previous.tredictRetryAt !== 'string') return null;
  const at = Date.parse(previous.tredictRetryAt);
  const ahead = at - now;
  return ahead > 0 && ahead <= TREDICT_PAUSE_MAX_S * 1000 ? new Date(at).toISOString() : null;
}

function tredictPauseUntil(now, retryAfterS) {
  const seconds = Number.isFinite(retryAfterS) ? retryAfterS : TREDICT_PAUSE_MIN_S;
  return new Date(now + Math.min(Math.max(seconds, TREDICT_PAUSE_MIN_S), TREDICT_PAUSE_MAX_S) * 1000).toISOString();
}

// Plan, activities, efforts one at a time; the first failure ends the sequence, since the panels fall back as a whole
async function fetchPanels(sequence, urls) {
  const plan = embeddedList(await sequence.call(urls.plan), 'plannedWorkoutList');
  if (!plan.ok) return { plan, activities: SKIPPED, efforts: SKIPPED };
  const activities = embeddedList(await sequence.call(urls.activities), 'activityList');
  if (!activities.ok) return { plan, activities, efforts: SKIPPED };
  return { plan, activities, efforts: effortsOf(await sequence.call(urls.efforts)) };
}

// The panels' calls, then this week's uncached detail calls on the same sequence. The week needs the run's zone,
// which only the weather retry knows when the user has none.
async function fetchTredict(sequence, urls, { zone, now, sport, previous }) {
  const results = await fetchPanels(sequence, urls);
  if (![results.plan, results.activities, results.efforts].every(part => part.ok)) return results;
  const week = buildWeek({ plans: results.plan.list, activities: results.activities.list, now, tz: await zone, sport });
  const ids = [...new Set(week.done.map(entry => entry.id))];
  const cache = readIntensityCache(isObject(previous) ? previous.intensityCache : null);
  await fetchIntensity(sequence, ids, cache);
  return { ...results, week, ids, cache };
}

// Newest first, within the per-run budget and deadline. A 404 (or a body without the field) is cached as zeros, since
// asking again won't help; any other failure leaves the id for a later run and ends the detail calls, as does a 429.
async function fetchIntensity(sequence, ids, cache) {
  let calls = 0;
  for (const id of ids) {
    if (cache.has(id)) continue;
    if (calls >= INTENSITY_PER_RUN || sequence.stopped() || sequence.remaining() < DETAIL_MIN_MS) return;
    calls += 1;
    const result = await sequence.call(detailUrl(id));
    if (result.ok) cache.set(id, intensityOf(result.data));
    else if (result.kind === 'missing') cache.set(id, [0, 0, 0]);
    else return;
  }
}

// The previous output's cache as it was, for runs that don't know this week's ids
function carriedCache(previous) {
  const cache = readIntensityCache(isObject(previous) ? previous.intensityCache : null);
  return cacheList(cache, [...cache.keys()]);
}

const zoneOf = value =>
  isObject(value) && isObject(value.location) && isZone(value.location.timezone) ? value.location.timezone : null;

// A 2xx object without its list is an empty list (a new account); anything else is unreadable
function embeddedList(result, key) {
  if (!result.ok) return { ok: false, kind: result.kind };
  if (!isObject(result.data)) return { ok: false, kind: 'unavailable' };
  const embedded = isObject(result.data._embedded) ? result.data._embedded : {};
  return { ok: true, list: Array.isArray(embedded[key]) ? embedded[key] : [] };
}

// No keys is an empty account. It only gives the empty form when the plan and activity calls also succeeded: any
// other failure already makes the Tredict state unavailable, stale, paused, auth or payment.
function effortsOf(result) {
  if (!result.ok) return { ok: false, kind: result.kind };
  const efforts = isObject(result.data) ? result.data.trainingEfforts : null;
  if (!isObject(efforts)) return { ok: false, kind: 'unavailable' };
  return { ok: true, efforts };
}

// Field by field from the contract, so nothing else in a previous output survives
function reuseWeek(week) {
  if (!isObject(week) || !Array.isArray(week.days)) return null;
  return {
    title: textOf(week.title),
    days: week.days.filter(isObject).map(day => ({
      label: textOf(day.label),
      today: day.today === true,
      items: (Array.isArray(day.items) ? day.items : []).filter(isObject).map(item => ({
        kind: ITEM_KINDS.includes(item.kind) ? item.kind : 'planned',
        text: textOf(item.text)
      })),
      more: textOf(day.more)
    })),
    footer: textOf(week.footer),
    garmin: (Array.isArray(week.garmin) ? week.garmin : []).filter(name => typeof name === 'string')
  };
}

function reuseIntensity(intensity) {
  if (!isObject(intensity) || typeof intensity.heading !== 'string') return null;
  const { segments, labels } = intensity;
  if (!Array.isArray(segments) || segments.length > INTENSITY_KINDS.length) return null;
  if (!Array.isArray(labels) || labels.length !== 3 || !labels.every(label => typeof label === 'string')) return null;
  const valid = segment =>
    isObject(segment) &&
    INTENSITY_KINDS.includes(segment.kind) &&
    isFiniteNumber(segment.x) &&
    isFiniteNumber(segment.width);
  if (!segments.every(valid)) return null;
  return {
    heading: intensity.heading,
    segments: segments.map(({ kind, x, width }) => ({ kind, x, width })),
    labels: labels.slice(),
    garmin: (Array.isArray(intensity.garmin) ? intensity.garmin : []).filter(name => typeof name === 'string')
  };
}

function reuseForm(form) {
  if (!isObject(form)) return null;
  const labels = isObject(form.labels) ? form.labels : {};
  const path = value => (typeof value === 'string' && REUSED_PATH.test(value) ? value : '');
  return {
    heading: textOf(form.heading),
    today: textOf(form.today),
    pastPath: path(form.pastPath),
    futurePath: path(form.futurePath),
    zeroY: finiteOf(form.zeroY),
    todayX: finiteOf(form.todayX),
    labels: { back: textOf(labels.back), today: textOf(labels.today), ahead: textOf(labels.ahead) },
    empty: textOf(form.empty)
  };
}

// Last good data: only from a v1 output with both panels whose Tredict fetch was today (local)
function staleTredict(previous, now, tz) {
  if (!isObject(previous) || previous.v !== BOARD_VERSION) return null;
  const at = typeof previous.tredictAt === 'string' ? Date.parse(previous.tredictAt) : NaN;
  if (!Number.isFinite(at) || localDate(at, tz) !== localDate(now, tz)) return null;
  const week = reuseWeek(previous.week);
  const form = reuseForm(previous.form);
  if (!week || !form) return null;
  return {
    week,
    form,
    intensity: reuseIntensity(previous.intensity),
    tredictAt: previous.tredictAt,
    tredictAtText: textOf(previous.tredictAtText)
  };
}

function tredictPanels({ results, previous, now, tz, lang, fetchedAt, fetchedAtText }) {
  const text = STRINGS[lang];
  const { plan, activities, efforts } = results;
  const parts = [plan, activities, efforts];
  const failed = kind => parts.some(part => !part.ok && part.kind === kind);
  const empty = {
    week: null,
    form: null,
    intensity: null,
    garmin: [],
    intensityCache: carriedCache(previous),
    tredictAt: null,
    tredictAtText: ''
  };

  if (failed('paused')) return { state: 'paused', message: text.tokenPaused, ...empty };
  if (failed('auth')) return { state: 'auth', message: text.tokenInvalid, ...empty };
  if (failed('payment')) return { state: 'payment', message: text.tredictPayment, ...empty };
  if (parts.some(part => !part.ok)) {
    const stale = staleTredict(previous, now, tz);
    if (!stale) return { state: 'unavailable', message: text.tredictUnavailable, ...empty };
    return {
      state: 'stale',
      message: fill(text.tredictDataFrom, { time: stale.tredictAtText }),
      ...empty,
      ...stale,
      garmin: union(stale.week.garmin, stale.intensity ? stale.intensity.garmin : [])
    };
  }

  const { week, ids, cache } = results;
  const series = formSeries({ efforts: efforts.efforts, today: localDate(now, tz) });
  // The bar only once every run of this week is cached
  const complete = ids.every(id => cache.has(id));
  const entries = ids.map(id => cache.get(id));
  const view = complete ? intensityView(entries, lang) : null;
  // The bar keeps the Garmin texts of the runs that add to it, so stale panels can attribute them too
  const adds = entry => entry.garmin !== null && cache.get(entry.id).some(value => value > 0);
  const intensity = view && { ...view, garmin: union(week.done.filter(adds).map(entry => entry.garmin)) };
  // The footer: the calendar rows' Garmin texts, then the bar's
  const garmin = union(week.garmin, intensity ? intensity.garmin : []);
  return {
    state: 'ok',
    message: '',
    week: weekView(week, lang),
    form: formChart(series, lang),
    intensity,
    garmin,
    intensityCache: cacheList(cache, ids),
    tredictAt: fetchedAt,
    tredictAtText: fetchedAtText
  };
}

// Read before assembly, so the fixed error output can still carry the previous pause
function previousOf(input) {
  try {
    const trmnl = isObject(input) && isObject(input.trmnl) ? input.trmnl : {};
    return isObject(trmnl.previous_merge_variables) ? trmnl.previous_merge_variables : null;
  } catch {
    return null;
  }
}

async function assembleBoard(input, { fetch: fetchFn, now, timeoutMs, clock, previous, carry }) {
  const body = isObject(input) ? input : {};
  const trmnl = isObject(body.trmnl) ? body.trmnl : {};
  const user = isObject(trmnl.user) ? trmnl.user : {};
  const settings = readSettings(body);
  const lang = resolveLanguage(settings.language, user.locale);
  const text = STRINGS[lang];
  const userZone = isZone(user.time_zone_iana) ? user.time_zone_iana : null;
  const polled = typeof body.generatedAt === 'string';
  // The range has a day of margin on each side, so a retry body's zone (not known yet) can't move it out of the week
  const rangeZone = userZone || zoneOf(body) || 'UTC';

  const urls = tredictUrls(tredictRange(now, rangeZone));
  // While a 429 pause is in force no Tredict call is made at all, and the panels take the stale path
  const tredictPause = recentTredictPause(previous, now);
  const sequence = tredictPause ? null : tredictSequence({ fetch: fetchFn, token: settings.token, clock });
  const pausedRetryAt = recentWeatherRetry(previous, now);
  const retry = !polled && settings.hasLocation && !pausedRetryAt;
  // Runs alongside the Tredict calls; the detail calls wait for it only when the week's zone depends on it
  const weatherCall = retry ? fetchWindow(fetchFn, windowUrl(settings), timeoutMs) : Promise.resolve(null);
  // Calendar, form and intensity: the user's zone, else the zone of the window body used
  const zone = weatherCall.then(weather => userZone || zoneOf(polled ? body : weather && weather.body) || 'UTC');
  const [results, weather] = await Promise.all([
    sequence
      ? fetchTredict(sequence, urls, { zone, now, sport: settings.sport, previous })
      : { plan: SKIPPED, activities: SKIPPED, efforts: SKIPPED },
    weatherCall
  ]);
  const rate = sequence ? sequence.rate() : null;
  const tredictRetryAt = rate ? tredictPauseUntil(now, rate.retryAfterS) : tredictPause;
  carry.tredictRetryAt = tredictRetryAt;

  const windowBody = polled ? body : weather && weather.body;
  const tz = await zone;
  // The run window: the API's zone
  const apiZone = zoneOf(windowBody) || tz;
  let weatherRetryAt = null;
  if (retry) weatherRetryAt = new Date(now).toISOString();
  else if (!polled && settings.hasLocation) weatherRetryAt = pausedRetryAt;

  const fetchedAt = new Date(now).toISOString();
  const fetchedAtText = dayAndTime(now, tz, text);
  const { plan } = results;
  const tredict = tredictPanels({ results, previous, now, tz, lang, fetchedAt, fetchedAtText });
  carry.intensityCache = tredict.intensityCache;

  const session = pickSession({
    plans: plan.ok ? plan.list : null,
    now,
    tz: apiZone,
    avail: settings.availability,
    sport: settings.sport
  });
  const run = windowPanel({
    body: windowBody,
    status: weather ? weather.status : null,
    session,
    lang,
    hasLocation: settings.hasLocation
  });

  const attribution = tredict.garmin.slice();
  if (WEATHER_KINDS.includes(run.kind) && isObject(windowBody) && typeof windowBody.attribution === 'string') {
    attribution.push(windowBody.attribution);
  }

  const { state, message, tredictAt, tredictAtText, week, form, intensity, intensityCache } = tredict;
  return {
    v: BOARD_VERSION,
    lang,
    fetchedAt,
    fetchedAtText,
    tredict: { state, message },
    tredictAt,
    tredictAtText,
    week,
    form,
    intensity,
    run,
    weatherRetryAt,
    tredictRetryAt,
    intensityCache,
    attribution: attribution.filter(Boolean).join(ATTRIBUTION_SEPARATOR)
  };
}

// Never rejects: anything unexpected gives the fixed error output. `timeoutMs` is the weather retry's; Tredict calls
// take theirs from the sequence's deadline, which `clock` drives.
async function buildBoard(input, { fetch: fetchFn, now, timeoutMs = REQUEST_TIMEOUT_MS, clock = Date.now } = {}) {
  const previous = previousOf(input);
  // What this run has worked out so far that must survive a throw: its Tredict pause and its intensity cache
  const carry = {};
  try {
    return await assembleBoard(input, { fetch: fetchFn, now, timeoutMs, clock, previous, carry });
  } catch {
    return errorBoard(now, previous, carry);
  }
}

async function run(input) {
  try {
    return await buildBoard(input, { fetch, now: Date.now() });
  } catch {
    return {
      v: 1,
      lang: 'en',
      fetchedAt: new Date(Date.now()).toISOString(),
      fetchedAtText: '',
      tredict: { state: 'unavailable', message: 'Tredict unavailable' },
      tredictAt: null,
      tredictAtText: '',
      week: null,
      form: null,
      intensity: null,
      run: { kind: 'error', heading: 'Weather unavailable', lines: [] },
      weatherRetryAt: null,
      tredictRetryAt: null,
      intensityCache: [],
      attribution: ''
    };
  }
}
